     */
    function ejecutar_base($sql, $basededatos){

        
        $this->db =  $this->load->database($basededatos, TRUE);        
        
        $this->db->query($sql);
        $resultado =  $this->db->insert_id();
        
        $this->db =  $this->load->database("default", TRUE);        
        
        return $resultado;
    }
    
