    function get_ventas_enlinea($condicion)
    {    

        $sql = "select v.*, b.banco_nombre,f.factura_tokendelegado, f.factura_ambiente, 
                f.factura_cuis, f.factura_cufd, f.factura_modalidad, f.factura_codsistema, 
